from dotenv import load_dotenv
import os
from langchain_google_genai import ChatGoogleGenerativeAI
from langchain_core.prompts import PromptTemplate, ChatPromptTemplate
from langchain_core.output_parsers import StrOutputParser

load_dotenv()

API_KEY = os.getenv("API_KEY")

modelo = ChatGoogleGenerativeAI(model="gemini-3.5-flash", api_key=API_KEY)

#f-strings
plantilla = PromptTemplate.from_template(
  "Explica el concepto de {tema} en un parrafo para alguien que recien comienza en {tarea}"
)

cadena_simple = plantilla | modelo | StrOutputParser()
respuesta = cadena_simple.invoke({"tema": "embeddings", "tarea": "búsqueda semántica"})

print(respuesta)

plantilla_control = ChatPromptTemplate.from_messages([
  ("system", "Eres un experto en el área correspondiente, vas a responder siempre con texto simple para el usuario."),
  ("human", "Explica el concepto de {tema} en un párrafo, para alguien que recién comienza en {area}")
])

